// Set to 1 to automatically open before/after AST diff tabs in VS Code, 0 to
// disable
#define OPEN_VSCODE_DIFF 1

#pragma region Parameterized Test Setup

struct SemanticTestCase {
  std::string name;
  std::function<ast_node_t *()> build_ast;
  err_code_t expected_err = NO_ERR;
  bool expect_main = true;
};

class SemanticAnalyserParamTest
    : public ::testing::TestWithParam<SemanticTestCase> {
protected:
  std::string before_file_;
  std::string after_file_;

  void run_analysis(ast_node_t *root, hashtable_t *symtable,
                    ast_node_t **main_node_out, err_code_t *result_out) {
    const ::testing::TestInfo *info =
        ::testing::UnitTest::GetInstance()->current_test_info();

    std::string suite_name =
        (info != nullptr) ? info->test_suite_name() : "unknown_suite";
    for (char &c : suite_name) {
      if (c == '/') {
        c = '_';
      }
    }

    std::string test_id = suite_name + "_" + GetParam().name;

    std::filesystem::create_directories(".ast_diffs");
    before_file_ = ".ast_diffs/" + test_id + "_before.ast";
    after_file_ = ".ast_diffs/" + test_id + "_after.ast";

    dump_ast_to_file(before_file_.c_str(), root);
    *result_out = analyse(root, symtable, main_node_out);
    dump_ast_to_file(after_file_.c_str(), root);
  }

  void TearDown() override {
#if OPEN_VSCODE_DIFF
    if (HasFailure() && !before_file_.empty() && !after_file_.empty()) {
      std::string cmd =
          "code -r --diff \"" + before_file_ + "\" \"" + after_file_ + "\"";
      int rc = std::system(cmd.c_str());
      (void)rc;
    }
#endif
  }
};

